class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        res = []
        if len(nums) == 1:
            return [nums.copy()]
        for i in range(len(nums)):
            n = nums.pop(0)
            perms = self.permute(nums)
            for p in perms:
                p.append(n)
            res.extend(perms)
            nums.append(n)
        return res

reference_solution.javascript:
function permute(nums) {
    const res = [];
    function backtrack(path, remaining) {
        if (remaining.length === 0) {
            res.push([...path]);
            return;
        }
        for (let i = 0; i < remaining.length; i++) {
            path.push(remaining[i]);
            backtrack(path, remaining.filter((_, idx) => idx !== i));
            path.pop();
        }
    }
    backtrack([], nums);
    return res;
}
